window.kbPageData["views/entry/k-57e522a7d0c4a9a1"] = {"key":"entry/k-57e522a7d0c4a9a1","state":{"route":"entry/k-57e522a7d0c4a9a1"},"node":{"id":"k-57e522a7d0c4a9a1","mode":"k","title":"用年均增速判断两期比重升降","type":"原理与机制","domain":"统计","reading":"","intro":"","priority":100,"aliases":["按同一期间的年均增速判断两期比重升降"],"qs":["江苏 2023 B类 行测#117"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"部分量和整体量的基期值均为正，且年均增速对应同一起止时期时，部分量的年均增速低于整体量，比重下降。部分量的年均增速高于整体量，比重上升。两者相等时，比重不变。","review":{"definition":"部分量和整体量的基期值均为正，且年均增速对应同一起止时期时，部分量的年均增速低于整体量，比重下降。部分量的年均增速高于整体量，比重上升。两者相等时，比重不变。","explanation":"同一时期内，年均增速越高，按相同年数复合得到的累计增长倍数就越大。末期比重等于基期比重乘以部分量与整体量的累计增长倍数之比。第117题中，制造业增加值年均增长6.4%，低于国内生产总值的6.6%，所以其占比在2021年比2012年下降，选A。规模以上装备制造业、服务业和规模以上高技术制造业的年均增速分别为9.2%、7.4%和11.6%，均高于6.6%。","references":[],"evidence":"当部分增长率\n<整体增长率时，比重下降","disposition":"独立词条","basis":"据原题和解析编释。"}},"questions":{"江苏 2023 B类 行测#117":{"paper":"江苏 2023 B类 行测","n":117,"mod":"资料分析","src":["22262c34d18cd68fbee4.pdf",23],"asrc":["b08f2713d73015eac675.pdf",38],"card":"b8cda16111985ed79c975531","links":[{"id":"k-57e522a7d0c4a9a1","role":"解题依据","why":"在起止年份相同的条件下，年均增速与累计增速的排序一致，部分增速低于整体增速时比重下降。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-57e522a7d0c4a9a1":[["江苏 2023 B类 行测#117"]]}};
